import re

from ..robot_compatibility import TestData, TestCase

REGEXPS = {
    "QC": re.compile(r"^QC_(.*)", re.MULTILINE),
    "FT": re.compile(r"^FT_(.*)", re.MULTILINE),
    "CA": re.compile(r"^CA_(.*)", re.MULTILINE),
    "PH": re.compile(r"^PH_(.*)", re.MULTILINE),
    "QCD": re.compile(r"^QCD_(.*)", re.MULTILINE),
    "QCP": re.compile(r"^QCP_(.*)", re.MULTILINE),
    "MAP_TC": re.compile(r"^MAP_TC_(.*)", re.MULTILINE),
    "MQC": re.compile(r"^MQC.*", re.MULTILINE),
    "TC_ID": re.compile(r"^ute:id:(.*)", re.MULTILINE),
}


def get_tags_from_test(test: TestCase, regexp_name: str):
    """Method used to get tags from test suite output file

    :param string    test:            test name
    :param string    regexp_name:     regular expression to be found

    :return: list of matched tags
    :rtype: list
    """
    tags = "\n".join(test.tags)
    match_tags = REGEXPS[regexp_name].findall(tags)
    return match_tags


def get_single_tag_from_test(test: TestCase, regexp_name: str, converter=None):
    """Method used to get tags from test suite output file

    :param string    test:            test name
    :param string    regexp_name:     regular expression to be found

    :return: matched tag
    :rtype: string
    """
    tags = get_tags_from_test(test, regexp_name)
    if tags:
        if converter is not None:
            return converter(tags[0])
        return tags[0]


def get_tags_from_suite_force_tags(suite: TestData, regexp_name: str):
    """Method used to get tags from suite settings Force Tags section

    :param string    suite:           TestData suite instance
    :param string    regexp_name:     regular expression to be found

    :return: matched tag
    :rtype: string
    """
    try:
        tags = "\n".join(suite.setting_table.test_tags)
    except AttributeError:
        tags = "\n".join(suite.setting_table.force_tags)
    match_tags = REGEXPS[regexp_name].findall(tags)
    if match_tags:
        return match_tags[0]
